-- MealFit 테스트용 seed 데이터 (정제 완료 상태)
--
-- 크롤링 → 정규화 → 식약처 매칭 → LLM 보조 매칭 → 태깅까지 끝난 결과입니다.
-- 이 파일만 넣으면 Playwright·Ollama·Gemini·식약처 xlsx 없이 API를 테스트할 수 있습니다.
--
-- 포함: 식당·메뉴·음식종류 태그·식약처 식품(참조분)·동의어 사전·LLM 판정 캐시
-- 제외: 회원·인바디 등 개인정보 일체
--
-- 사용법:
--   mysql -u root -p mealfit_test < sql/schema_additions.sql
--   mysql -u root -p mealfit_test < sql/seed_test_data.sql
--
-- INSERT IGNORE라 여러 번 실행해도 안전합니다.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

